from pyspark.sql import functions as F, DataFrame
from pyspark.sql.window import Window
from pyspark.sql.types import *
dbutils.widgets.text("target_catalog", "agentops")
dbutils.widgets.text("target_schema", "gold")
dbutils.widgets.text("run_mode", "run")   # "library" = only define functions (tests import the notebook this way)
TARGET_CATALOG = dbutils.widgets.get("target_catalog"); TARGET_SCHEMA = dbutils.widgets.get("target_schema"); RUN_MODE = dbutils.widgets.get("run_mode")

# COMMAND ----------
def build(spark, sources: dict) -> dict:
    # Output table grain: one row per (provider_id, provider_name, provider_state, claim_month)
    # BUSINESS RULES IMPLEMENTED (preserve existing unless noted):
    # - Month driver: billable_start (service start). Parse with ANSI-safe coalesce of formats; derive claim_month = date_trunc('month', ts)::date
    # - Exclude rows where claim_month is null (unparseable billable_start)
    # - Exclude claims with status in {'cancelled','entered-in-error'} (case-insensitive)
    # - Deduplicate claims by claim_id prior to aggregation:
    #     ROW_NUMBER() OVER (PARTITION BY claim_id ORDER BY _ingested_at DESC, status DESC, total_value DESC) = 1
    # - Provider enrichment: LEFT JOIN organization on claim.provider_id = organization.organization_id
    #     Null-handling: if unmatched, provider_name='Unknown provider', provider_state='Unknown'
    # - Metrics:
    #     claims_count = COUNT(DISTINCT claim_id) after dedup
    #     amount_billed = SUM(COALESCE(total_value, 0.0)) including negatives; cast to decimal(18,2) at the end
    #     denied_or_rejected_claims_count = COUNT(DISTINCT claim_id) where lower(status) in ('denied','rejected')
    #     denial_rate = ratio 0–1: try_divide(denied_or_rejected_claims_count, claims_count); 0 when claims_count=0
    # - Non-null grain keys: ensure provider_id and claim_month are not null at final projection
    claim_src = sources["claim"].alias("clm_src")
    org_src = sources["organization"].alias("org_src")

    # Deduplicate claims on claim_id keeping the latest by _ingested_at, then status desc, then total_value desc (deterministic tie-breaker)
    w_claim = Window.partitionBy(F.col("clm_src.claim_id")).orderBy(
        F.col("clm_src._ingested_at").desc_nulls_last(),
        F.col("clm_src.status").desc_nulls_last(),
        F.col("clm_src.total_value").desc_nulls_last()
    )
    clm_dedup = (
        claim_src
        # Normalize status for downstream filters and flags
        .withColumn("status_l", F.lower(F.col("clm_src.status")))
        # Parse billable_start with mixed formats safely in ANSI mode
        .withColumn(
            "billable_start_ts",
            F.coalesce(
                F.expr("try_to_timestamp(billable_start)"),
                F.expr("try_to_timestamp(billable_start, 'MM/dd/yyyy HH:mm')")
            )
        )
        .withColumn("claim_month", F.date_trunc("month", F.col("billable_start_ts")).cast("date"))
        # Exclude cancelled and entered-in-error if present (case-insensitive)
        .withColumn(
            "is_excluded_status",
            F.when(F.col("status_l").isin("cancelled", "entered-in-error"), F.lit(1)).otherwise(F.lit(0))
        )
        .withColumn("rn", F.row_number().over(w_claim))
        .where(F.col("rn") == F.lit(1))
        # Exclude unparsable month and excluded statuses
        .where(F.col("claim_month").isNotNull())
        .where(F.col("is_excluded_status") == F.lit(0))
        # Prepare clean billed amount (double), treat nulls as 0.0 (included as-is, currency not filtered)
        .withColumn("billed_amount_clean", F.coalesce(F.col("clm_src.total_value"), F.lit(0.0)))
        # Flags for denial/rejection
        .withColumn(
            "is_denied_or_rejected",
            F.when(F.col("status_l").isin("denied", "rejected"), F.lit(1)).otherwise(F.lit(0))
        )
        .select(
            F.col("clm_src.claim_id").alias("claim_id"),
            F.col("clm_src.provider_id").alias("provider_id"),
            F.col("claim_month"),
            F.col("billed_amount_clean"),
            F.col("is_denied_or_rejected")
        )
        .alias("c")
    )

    # Left join to organization to enrich provider_name and provider_state; maintain unmatched with explicit defaults
    org_dedup = (
        org_src
        .dropDuplicates(["organization_id"])
        .select(
            F.col("org_src.organization_id").alias("organization_id"),
            F.col("org_src.org_name").alias("org_name"),
            F.col("org_src.org_state").alias("org_state")
        )
        .alias("o")
    )

    joined = (
        clm_dedup.join(org_dedup, on=F.col("c.provider_id") == F.col("o.organization_id"), how="left")
        .withColumn("provider_name", F.coalesce(F.col("o.org_name"), F.lit("Unknown provider")))
        .withColumn("provider_state", F.coalesce(F.col("o.org_state"), F.lit("Unknown")))
        .select(
            F.col("c.provider_id").alias("provider_id"),
            F.col("provider_name"),
            F.col("provider_state"),
            F.col("c.claim_month").alias("claim_month"),
            F.col("c.claim_id").alias("claim_id"),
            F.col("c.billed_amount_clean").alias("billed_amount_clean"),
            F.col("c.is_denied_or_rejected").alias("is_denied_or_rejected")
        )
        .alias("j")
    )

    # Aggregate to provider-month grain
    agg = (
        joined.groupBy(
            F.col("j.provider_id"),
            F.col("j.provider_name"),
            F.col("j.provider_state"),
            F.col("j.claim_month")
        )
        .agg(
            F.countDistinct(F.col("j.claim_id")).alias("claims_count"),
            F.sum(F.col("j.billed_amount_clean")).alias("amount_billed_raw"),
            F.sum(F.col("j.is_denied_or_rejected")).cast("long").alias("denied_or_rejected_claims_count_raw")
        )
        .alias("g")
    )

    # Final typing and denial_rate as ratio (0-1); ensure non-null grain keys
    result = (
        agg
        .withColumn("amount_billed", F.expr("try_cast(amount_billed_raw AS DECIMAL(18,2))"))
        .withColumn("denied_or_rejected_claims_count", F.col("denied_or_rejected_claims_count_raw").cast("long"))
        .withColumn(
            "denial_rate",
            F.when(F.col("claims_count") > F.lit(0),
                   F.expr("try_divide(denied_or_rejected_claims_count, claims_count)")
            ).otherwise(F.lit(0.0))
        )
        .select(
            F.col("g.provider_id"),
            F.col("g.provider_name"),
            F.col("g.provider_state"),
            F.col("g.claim_month"),
            F.col("g.claims_count"),
            F.col("amount_billed"),
            F.col("denied_or_rejected_claims_count"),
            F.col("denial_rate")
        )
        .where(F.col("provider_id").isNotNull())
        .where(F.col("claim_month").isNotNull())
        .alias("provider_claims_denial_monthly")
    )

    return {
        "provider_claims_denial_monthly": result
    }

# COMMAND ----------
def load_sources(spark) -> dict:
    return {
        "claim": spark.table("agentops.bronze.claim"),
        "organization": spark.table("agentops.bronze.organization"),
    }

# COMMAND ----------
if RUN_MODE == "run" and not globals().get("AGENTOPS_LIBRARY_MODE", False):
    outputs = build(spark, load_sources(spark))
    spark.sql(f"CREATE SCHEMA IF NOT EXISTS {TARGET_CATALOG}.{TARGET_SCHEMA}")
    for name, df in outputs.items():
        df.write.format("delta").mode("overwrite").option("overwriteSchema", "true").saveAsTable(f"{TARGET_CATALOG}.{TARGET_SCHEMA}.{name}")